fn solve(a: i8, b: i8, c: i8) -> i8 {
    // To avoid overflow when summing sides, work in a larger integer type
    let mut sides = [a as i16, b as i16, c as i16];
    sides.sort(); // now sides[0] <= sides[1] <= sides[2]
    let x = sides[0];
    let y = sides[1];
    let z = sides[2];

    // We need x + y > z.  If x + y <= z, then we need (z - (x + y) + 1) increments.
    let need = z - (x + y) + 1;
    if need > 0 {
        // need will fit in i8 since max possible is when z=100, x+y=2, so need=99
        need as i8
    } else {
        0
    }
}